import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"InspectorFrame","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/inspector-frame.md","filePath":"workbench/inspector-frame.md"}'),n={name:"workbench/inspector-frame.md"};function r(i,e,s,c,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="inspectorframe" tabindex="-1">InspectorFrame <a class="header-anchor" href="#inspectorframe" aria-label="Permalink to &quot;InspectorFrame&quot;">​</a></h1><p>InspectorFrame is the panel of the thing selected: its name, changed where it stands, the tabs of its views and the sections that edit it.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the panel that shows one selected thing and lets it be changed, beside the stage. The application decides what the thing is: it passes the name, the tabs and, as children, the <a href="./inspector-section">InspectorSection</a> groups of the current tab, filled with <a href="./inspector-row">InspectorRow</a> rows, a <a href="./field-list">FieldList</a> or an <a href="./attribute-list">AttributeList</a>. When several things are selected, use <a href="./selection-summary">SelectionSummary</a> instead.</p><p>Pass <code>ontitle</code> to let the name be changed. The frame shows <code>title</code>; when a name is committed, <code>ontitle</code> receives it trimmed and the application updates <code>title</code>, or the name goes back to it. So the application decides what an empty name means: keep the old one, or put a default in its place.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The name of the thing shown</td></tr><tr><td><code>ontitle</code></td><td></td><td>Called with the name committed; without it, no editing</td></tr><tr><td><code>titleEditable</code></td><td><code>true</code></td><td><code>false</code> shows the name as a title only</td></tr><tr><td><code>placeholder</code></td><td><code>addName</code> message</td><td>The action shown while the name is empty</td></tr><tr><td><code>subtitle</code></td><td></td><td>A second line under the name</td></tr><tr><td><code>icon</code></td><td></td><td>An icon before the name</td></tr><tr><td><code>tabs</code></td><td><code>[]</code></td><td>The views, <code>{ id, label }[]</code></td></tr><tr><td><code>current</code></td><td>the first tab</td><td>The id of the current tab (bindable)</td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the tab that is opened</td></tr><tr><td><code>head</code></td><td></td><td>Icon buttons in the head, before the close button (a snippet)</td></tr><tr><td><code>underHead</code></td><td></td><td>A band under the head, above the tabs (a snippet)</td></tr><tr><td><code>end</code></td><td></td><td>The foot, a <a href="./../components/footer">Footer</a> with the actions (a snippet)</td></tr><tr><td><code>onclose</code></td><td></td><td>Shows a close button in the head</td></tr><tr><td><code>side</code></td><td><code>panel</code></td><td>The width, as <a href="./../components/panel">Panel</a>&#39;s <code>side</code></td></tr><tr><td><code>children</code></td><td>required</td><td>The sections of the current tab</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/panel">Panel</a> whose head is a <a href="./../components/toolbar">Toolbar</a>: the icon, the name, the controls of <code>head</code> and the close button, in that order. The name is an <a href="./../components/inline-edit">InlineEdit</a> at the size of h2, named by the <code>rename</code> message (Enter commits, Escape restores), or, not editable, a title on one line with an ellipsis. With a <code>subtitle</code>, the head grows to hold it as a muted caption under the name. With <code>tabs</code>, a second Toolbar under the head holds the <a href="./../components/tabs">Tabs</a>, and its line is the one line of the head; without, the head draws the line. <code>underHead</code> is placed right under the head and above the tabs, with no distance of its own: a band of the application, such as a palette in a <a href="./../components/block">Block</a>, that keeps its place while the content scrolls. The content is stacked with gap 0 and scrolls; the foot keeps its height. The panel is a region named by the name.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/inspector-frame/" title="InspectorFrame" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/inspector-frame/" target="_blank" rel="noopener">InspectorFrame</a></figcaption></figure>',11)])])}const f=t(n,[["render",r]]);export{m as __pageData,f as default};
